// Build Firecrawl search queries from request body
const body = $input.first().json.body;
const industry = body.industry || '';
const audience = body.audience_description || '';
const keywords = (body.keywords || []).join(', ');
const location = body.location || '';
const platforms = body.platforms || ['reddit', 'youtube', 'linkedin'];
const focus = body.focus || 'all';

// Build 3–5 targeted queries
const queries = [];

// Core industry + pain point query
queries.push(`${industry} questions problems complaints ${location}`);

// Keyword-specific query (if keywords provided)
if (keywords) {
  queries.push(`${keywords} reddit OR youtube OR forum ${location}`);
}

// Audience conversation query
if (audience) {
  queries.push(`${audience.split(' ').slice(0, 6).join(' ')} advice help question`);
}

// Trend-focused query
if (focus === 'trends' || focus === 'all') {
  queries.push(`${industry} trending 2025 2026 what is growing`);
}

// Competitor gap query
if (focus === 'competitor_gaps' || focus === 'all') {
  queries.push(`${industry} nobody talks about hidden truth missing advice`);
}

// Local query (if location provided)
if (location && (focus === 'local' || focus === 'all')) {
  queries.push(`${industry} ${location} local community recommendations`);
}

return queries.slice(0, 5).map(q => ({ query: q, run_id: body.run_id, org_id: body.org_id }));

// Aggregate all Firecrawl results from each query iteration
const allItems = $input.all();
const combinedContent = allItems.map((item, i) => {
  const results = item.json.data || [];
  return results.map(r => `SOURCE [${i+1}]: ${r.url}\nTITLE: ${r.title}\nCONTENT:\n${(r.markdown || r.content || '').slice(0, 500)}`).join('\n\n---\n\n');
}).join('\n\n=====\n\n');

// Pass org context through
const first = allItems[0].json;
return [{ 
  content: combinedContent.slice(0, 12000),
  run_id: first.run_id || $('Webhook').first().json.body.run_id,
  org_id: first.org_id || $('Webhook').first().json.body.org_id,
  body: $('Webhook').first().json.body
}];

