const crypto = require('crypto');

const gptResponse = $input.first().json;
const webhookBody = $('Webhook').first().json.body;

// Parse GPT response
let parsed = {};
try {
  const content = gptResponse.choices[0].message.content;
  parsed = JSON.parse(content);
} catch (e) {
  parsed = { opportunities: [], social_signals: [] };
}

const payload = {
  workflow_type: 'growth_intelligence',
  status: 'complete',
  run_id: webhookBody.run_id,
  org_id: webhookBody.org_id,
  opportunities: (parsed.opportunities || []).map(o => ({
    ...o,
    content_formats: Array.isArray(o.content_formats) ? o.content_formats : [],
    hooks: Array.isArray(o.hooks) ? o.hooks : [],
    status: 'new',
  })),
  social_signals: (parsed.social_signals || []).map(s => ({
    ...s,
    location: s.location || null,
    source_url: s.source_url || null,
    engagement_hint: s.engagement_hint || null,
  })),
};

const body = JSON.stringify(payload);
const secret = process.env.N8N_HMAC_SECRET || '';
const signature = crypto.createHmac('sha256', secret).update(body).digest('hex');

return [{ body, signature, run_id: webhookBody.run_id }];

